from pathlib import Path
import json
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1]
OUT=BASE/'.cache/batch200/drafts/rewrite_spec';OUT.mkdir(parents=True,exist_ok=True)
X=[['拉丁 exterus／extrā','外面的；在外面']]
STR=X+[['拉丁 extrāneus → 古法语 estrange','外来的、不属于这里的'],['中古英语 straunge → 英语 strange','陌生的；进一步指不寻常、奇怪的']]
EST=X+[['拉丁 extrāneus → 通俗拉丁 *extrāneāre〔重建〕','外来的 → 使成为外人'],['古法语 estranger／estrangier → 英语 estrange','使疏远、使失去亲近关系']]
POL=X+[['英语 extra- 替换 interpolate 的 inter-','把“在里面推算”改成“往范围外推算”'],['英语 extrapolate','根据已有资料向未观察的范围推断']]
VAG=X+[['中世纪拉丁 extrāvagārī → extrāvagāns','走到范围外；其分词形'],['中古英语 extravagaunt，并受法语 extravagant 影响','原有教会法汇编之外的含义；后来发展出越界、过度等意思'],['英语 extravagant','花费奢侈的；过分夸张的']]
W=[
E('extra','/ˈekstrə/','额外的；额外地；附加项；临时演员','原来的一份已经有了，再从那一份之外加上一点。','独立词 extra 通常解释为 extraordinary 的缩略；前缀 extra- 则直接沿用拉丁 extrā“在……之外”。两者有关，但不是同一个借入过程。',X+[['拉丁 extrāordinārius → 英语 extraordinary','在通常次序或范围之外的'],['英语 extra〔缩略〕','额外的东西或程度；另发展出临时演员等用法']],'an extra chair 是原有椅子以外再添一把；pay extra 是多付钱。电影里的 an extra 通常只在背景出现、不担任主要对白角色。口语说 someone is extra，可指对方表现得太夸张、太用力。','extra time；an extra charge；cost extra；work as an extra。','extra 是多出来的；spare 常强调备用。an extra key 可以只是多一把，a spare key 强调留着应急。',('Could you bring an extra chair for our guest?','你能给客人再搬一把椅子吗？'),('Breakfast is included, but parking costs extra.','价格含早餐，但停车要另付费。'),('She worked as an extra in a scene set at a railway station.','她在一场火车站的戏里当了临时演员。'),sources=['https://www.etymonline.com/word/extra']),
E('strange','/streɪndʒ/','奇怪的；陌生的；不熟悉的','原本是“从圈子外面来的”，所以不熟悉；再从不熟悉变成看着不对劲。','经古法语 estrange 借入，远接拉丁 extrāneus“外来的”。不要把今天的 strange 生拆成 str- 和 ange。',STR,'a strange city 可以只是你第一次来，并没有什么怪事；a strange noise 则是声音不合常态。物理学的 strange quark 是“奇夸克”的专门名称，不是在评价它有多古怪。','feel strange；a strange place；It is strange that…；strange to say。','strange 的陌生和奇怪两层意思要看情境；unfamiliar 只说不熟悉，通常没有“不对劲”的判断。',('The streets felt strange on my first evening in the city.','初到这座城市的那个晚上，街道让我感到陌生。'),('There is a strange clicking sound coming from the fan.','风扇里传出一种奇怪的咔嗒声。'),sources=['https://en.wiktionary.org/wiki/strange#English','https://home.web.cern.ch/science/physics/standard-model/']),
E('exterior','英 /ɪkˈstɪəriə/；美 /ɪkˈstɪriər/','外部；外表；外部的','站在东西外面，看到或接触到的那一层。','借自拉丁 exterior，是 exterus“外面的”的比较级形；不能把现代 extra 当作它的直接母词。',X+[['拉丁 exterior','更在外面的；外部的'],['英语 exterior','物体外部，也可指人表现出来的样子']],'房子的 exterior 是外墙、外观这一面。人的 calm exterior 是外表表现得冷静，里面可能很紧张。作形容词常修饰墙面、门、表面等。','the exterior of a building；exterior walls；beneath a calm exterior。','exterior 与 interior 是外部和内部；appearance 范围更宽，还可谈出现、露面，不能处处替换。',('The exterior of the house was painted pale blue.','房子的外墙刷成了淡蓝色。'),('Behind his confident exterior, he was worried about the interview.','他外表很自信，心里却在担心面试。'),sources=['https://www.etymonline.com/word/exterior']),
E('strangely','/ˈstreɪndʒli/','奇怪地；说来也怪','事情的样子或发生方式，让人觉得不像平常那样。','现代可看作 strange + -ly；副词在中古英语已有 straungely 形式。',STR[:-1]+[['中古英语 straunge → straungely','从“陌生、奇怪”形成副词'],['英语 strangely','以不寻常的方式；也用于表达整件事出乎意料']],'He behaved strangely 是他的行为古怪；Strangely, he stayed calm 则是“奇怪的是，他竟然很镇定”。副词放句首时，往往评价后面的整个事实。','strangely quiet；act strangely；strangely enough。','strangely 不等于 suspiciously：让人觉得奇怪，不一定意味着可疑或做了坏事。',('The dog acted strangely when it heard the alarm.','狗听到警报后表现得很反常。'),('Strangely enough, I felt calmer after the interview began.','说来也怪，面试开始后我反而更平静了。')),
E('extraterrestrial','/ˌekstrətəˈrestriəl/','地球之外的；外星生物','把地球当作边界，研究或想象边界之外的东西。','extra-“在……之外” + terrestrial“地球的”，后者联系拉丁 terra“地、地球”；这是近代英语组合。',X+[['英语 extra- + terrestrial〔接拉丁 terra〕','在地球之外'],['英语 extraterrestrial','地外的；作名词可指外星生物']],'extraterrestrial life 是地外生命这一研究对象，不表示已经发现了它。名词 an extraterrestrial 常见于科幻作品；形容词也能修饰来自地球以外的物质。','extraterrestrial life；extraterrestrial intelligence；an extraterrestrial visitor。','extraterrestrial 跨出的是地球；extraterritorial 跨出的是领土或司法管辖范围。',('The researchers are searching for signs of extraterrestrial life.','研究人员正在寻找地外生命的迹象。'),('In the novel, an extraterrestrial learns human languages by listening to radio broadcasts.','小说里，一个外星生物通过收听广播学习人类语言。')),
E('extracellular','英 /ˌekstrəˈseljʊlə/；美 /ˌekstrəˈseljələr/','细胞外的','边界是细胞膜；膜外面的空间、液体或物质就可以叫 extracellular。','extra-“在外” + cellular“细胞的”，cellular 联系 cell；英语科学构词。',X+[['英语 extra- + cellular','在细胞之外'],['英语 extracellular','描述细胞外的液体、结构或过程']],'它不等于“人体外”：细胞之间的液体仍在身体里，却是 extracellular。extracellular matrix 像细胞周围的一张支撑网，帮助组织维持结构。','extracellular fluid；the extracellular matrix；extracellular proteins。','intracellular 在细胞里面，extracellular 在细胞外面；先找清楚所说的边界。',('The diagram shows fluid in the extracellular space.','这张图标出了细胞外间隙中的液体。'),('The cells attach to proteins in the extracellular matrix.','这些细胞附着在细胞外基质的蛋白质上。'),sources=['https://www.collinsdictionary.com/dictionary/english/extracellular']),
E('extraneous','/ɪkˈstreɪniəs/，亦 /ekˈstreɪniəs/','无关的；外来的；多余的','东西从外面混进来，却不是眼前这件事真正需要的部分。','直接借自拉丁 extrāneus“外来的”；strange 则经过法语进入英语，两词是不同路线来的同源词。',X+[['拉丁 extrāneus','外来的、不属于这里的'],['英语 extraneous','外来的；引申为与主题无关、多出来的']],'报告里的 extraneous details 可能每句都是真的，只是对结论没帮助。实验里的 extraneous noise 是额外混入的干扰，不一定是特别奇怪的声音。','extraneous information；remove extraneous details；extraneous to the discussion。','extra 只说多一点；extraneous 常说这部分与目的无关，留着反而添乱。',('Remove the extraneous details so the main argument is easier to follow.','删掉无关细节，让主要论点更容易理解。'),('The microphone picked up extraneous noise from the corridor.','麦克风收进了走廊里的额外噪声。')),
E('extramarital','/ˌekstrəˈmærɪtəl/','婚外的','已有婚姻是一条关系边界；跨到婚姻之外的亲密关系。','extra-“在……之外” + marital“婚姻的”；marital 联系拉丁 marītālis，不是 martial“军事的”。',X+[['英语 extra- + marital','在婚姻关系以外'],['英语 extramarital','常用于婚外恋情或性关系']],'这个词最常修饰 affair、relationship、sex，强调关系超出当事人已有婚姻。不是所有“婚姻之外的活动”都自然叫 extramarital；打球、上班通常不这样说。','an extramarital affair；an extramarital relationship。','premarital 是婚前的；extramarital 是已有婚姻之外的，两者划分的依据不同。',('The novel centres on the consequences of an extramarital affair.','这部小说围绕一段婚外情带来的后果展开。'),('She discovered that her husband had been involved in an extramarital relationship.','她发现丈夫曾有一段婚外关系。')),
E('extrajudicial','/ˌekstrədʒuːˈdɪʃəl/','司法程序之外的；未经司法程序的','该由司法程序处理的事，发生在那套程序之外。','extra-“在……之外” + judicial“司法的”；judicial 联系拉丁 iūdex“法官”。',X+[['英语 extra- + judicial','在司法程序之外'],['英语 extrajudicial','可中性描述诉讼外的行为，也可指绕过合法司法程序']],'extrajudicial statement 可只是法庭程序外的陈述；extrajudicial killing 则指没有合法司法程序的杀害，含义严重。不能因为都带 extra-，就把两种用法都淡化成“额外”。','an extrajudicial statement；extrajudicial killings；extrajudicial measures。','out of court 常见于庭外解决纠纷；extrajudicial 要看具体名词，可能包含缺乏合法权限或程序的意思。',('The article distinguishes testimony in court from extrajudicial statements.','文章区分了法庭证言与司法程序外的陈述。'),('The commission investigated reports of extrajudicial killings.','委员会调查了有关法外杀害的报告。'),sources=['https://www.merriam-webster.com/dictionary/extrajudicial']),
E('extrapolate','/ɪkˈstræpəleɪt/，亦 /ekˈstræpəleɪt/','外推；根据已有情况推断','已经看到一段走势，再把这条线往没看到的地方延长。','仿 interpolate 造词，把 inter-“在中间”换成 extra-“在外”；不能把后半段误认成 pole“柱子”。',POL,'已知第一到第五天的数据，估计第六天，是往范围外推。也可以从一个人群推测另一个人群，不一定涉及未来。能不能这样延长，取决于原有规律是否还适用。','extrapolate from the data；extrapolate a trend；extrapolate to a larger population。','interpolate 在已有数据点之间估计；extrapolate 到这些点覆盖的范围之外去估计。',('We cannot safely extrapolate next year’s sales from one unusually busy week.','不能仅凭一个异常忙碌的星期就可靠地推算明年的销量。'),('The model extrapolates the curve beyond the range of the measurements.','这个模型把曲线外推到了测量范围之外。'),sources=['https://www.etymonline.com/word/extrapolate']),
E('strangeness','/ˈstreɪndʒnəs/','奇怪；陌生感；奇异数〔物理〕','熟悉的参照突然没有了，于是感到不习惯或不寻常。','现代可看作 strange + -ness；中古英语已有 straungenesse。物理学后来借用这个词命名专门的量子数。',STR[:-1]+[['中古英语 straunge → straungenesse','由“陌生、奇怪”形成性质名词'],['英语 strangeness','不熟悉或奇怪的感觉；另有粒子物理术语义']],'日常说 the strangeness of a new place，强调新环境带来的陌生感。物理学里的 strangeness 是与奇夸克相关的量子数，数值有专门定义，不是衡量粒子“有多怪”。','a sense of strangeness；the strangeness of the situation；strangeness in particle physics。','strangeness 可来自不熟悉；mystery 强调尚未揭开的疑问，怪异感不一定伴随谜团。',('The strangeness of the empty station made her slow down.','空荡车站带来的陌生感让她放慢了脚步。'),('After a week, the strangeness of the new routine began to fade.','一星期后，新作息带来的不适应感开始消退。'),sources=['https://en.wiktionary.org/wiki/strangeness#English','https://cern-courier.web.cern.ch/a/strong-interactions/']),
E('estrangement','/ɪˈstreɪndʒmənt/','疏远；失和；关系隔阂','人还在，但曾经亲近的那条联系变得像陌生人之间一样。','现代可拆 estrange + -ment；来源有英语派生和古法语 estrangement 借入两种分析，均回到“使成为外人”的支线。',EST[:-1]+[['古法语 estranger／estrangement；英语 estrange + -ment','法语名词借入与英语派生两种来源分析'],['英语 estrangement','亲近关系的疏离或断裂']],'常见于家人、伴侣或朋友之间长期失和。它比“最近没见面”更重：即使住得近，也可能有 estrangement。','estrangement from one’s family；years of estrangement；a period of estrangement。','separation 可只是分开居住；estrangement 重点是感情和关系变疏远。',('They spoke again after years of estrangement.','多年失和之后，他们再次交谈了。'),('Her estrangement from her brother began with a dispute over their parents’ house.','她与哥哥的疏远始于对父母房子的争执。'),sources=['https://www.etymonline.com/word/estrangement','https://en.wiktionary.org/wiki/estrangement#English']),
E('extraterritorial','英 /ˌekstrəˌterɪˈtɔːriəl/；美 /ˌekstrəˌterəˈtɔːriəl/','域外的；涉及管辖领土之外的','把领土或管辖范围当作边界，作用却延伸到边界之外。','extra-“在……之外” + territorial“领土的”，后者联系拉丁 terra“土地”；英语组合。',X+[['英语 extra- + territorial','在某领土或管辖范围之外'],['英语 extraterritorial','如法律的域外适用；另可谈某些不受当地管辖的特权']],'extraterritorial application 常讨论一地的规则如何涉及境外行为。这个词本身不说明具体法律是否适用，也不能推出某地“没有法律”或使馆就是外国领土。','extraterritorial jurisdiction；extraterritorial application；extraterritorial rights。','extraterrestrial 是地球以外；extraterritorial 是某个领土或管辖边界以外，通常仍在地球上。',('The seminar examined the extraterritorial application of competition law.','研讨会讨论了竞争法的域外适用。'),('The historian described the extraterritorial privileges granted under the old treaty.','历史学家介绍了旧条约授予的治外法权特权。'),sources=['https://www.merriam-webster.com/dictionary/extraterritorial']),
E('estrange','/ɪˈstreɪndʒ/','使疏远；使失和','把本来属于亲近圈子的人，渐渐推成了圈子外的陌生人。','经古法语 estranger／estrangier，接重建的通俗拉丁 *extrāneāre；extrāneus 是“外来的”。不是现代英语先拿 strange 加 e- 造出来。',EST,'常用 estrange someone from someone：某件事让人彼此疏远。说 His behaviour estranged his friends，重点是行为伤害了关系，不是把朋友送到很远的地方。','estrange someone from their family；become estranged；estrange old friends。','alienate 还常指让支持者反感、失去认同；estrange 特别适合原本有亲近关系的人。',('Years of silence had estranged him from his daughter.','多年的沉默让他与女儿渐渐疏远。'),('Her repeated accusations estranged several close friends.','她一再指责别人，使几位亲密朋友与她疏远了。')),
E('stranger','英 /ˈstreɪndʒə/；美 /ˈstreɪndʒər/','陌生人；外来者','对你来说还没建立“我认识他”这条联系的人。','名词有古法语 estrangier“外来者”借入分析，也有 strange + -er 的英语派生分析；都接 extrāneus。它不是“比较奇怪的人”的缩写。',X+[['拉丁 extrāneus → 古法语 estrange／estrangier','外来的 → 外来者'],['中古英语 straunger → 英语 stranger','不认识的人；也有英语 strange + -er 的分析']],'陌生人可能就是本地居民；stranger 不必是外国人。be no stranger to something 则表示对某事很熟悉、有过经验。另外 strange 的比较级也拼 stranger，但那是“更奇怪”，要按句法区分。','a complete stranger；a stranger to the city；be no stranger to hardship。','foreigner 说国籍或来自外国；stranger 说是否认识。你可以认识很多外国人，也不认识住隔壁的人。',('A stranger helped me carry the suitcase up the stairs.','一位陌生人帮我把行李箱搬上楼。'),('She is no stranger to difficult negotiations.','她对艰难的谈判很有经验。'),sources=['https://www.etymonline.com/word/stranger']),
E('estranged','/ɪˈstreɪndʒd/','疏远的；失和的；分居的〔配偶〕','关系曾经很近，现在却疏远到不再正常来往。','estrange 的过去分词用作形容词；词尾 -ed 在这里读 /d/。',EST+[['英语 estrange → estranged','由“使疏远”变为“处在疏远状态”']],'an estranged husband 是关系破裂、已分开的丈夫，不一定已办离婚。estranged from her parents 说与父母失和，不等于住得远。','an estranged spouse；be estranged from one’s family；an estranged friend。','divorced 明确说已经离婚；estranged 只描述关系或分居状态，不能替它补上法律结论。',('He had been estranged from his father for several years.','他与父亲已疏远好几年。'),('Her estranged husband contacted her about their daughter’s school.','她分居的丈夫因女儿学校的事联系了她。')),
E('extrapolation','/ɪkˌstræpəˈleɪʃən/，亦 /ekˌstræpəˈleɪʃən/','外推；外推所得的估计','把已有趋势向外延长的过程，或者这样延长后得到的估计。','extrapolate + -ion，沿用 interpolation 的构词样式；重音移到 -lation 的 /leɪ/。',POL+[['英语 extrapolate + -ion → extrapolation','外推这一过程或结果']],'比如只测了低温区的数据，就估计高温区会怎样，这是一项 extrapolation。它不是瞎猜，但也不是新范围内的实测；原规律可能在边界外变了。','linear extrapolation；an extrapolation from limited data；extrapolation beyond the observed range。','prediction 是预测的广义名称；extrapolation 指把已有数据关系延伸到范围外的特定思路。',('The estimate is an extrapolation from only three years of records.','这个估计是根据仅有的三年记录外推出来的。'),('A straight-line extrapolation may fail if growth begins to slow.','如果增长开始放缓，直线外推就可能失准。'),sources=['https://www.etymonline.com/word/extrapolate']),
E('extramural','英 /ˌekstrəˈmjʊərəl/；美 /ˌekstrəˈmjʊrəl/','校外的；机构以外的','原图景是“墙外”，后来指学校或机构通常边界以外。','extra-“在外” + mural“墙的”，mural 接拉丁 mūrus“墙”；不是 extra + moral“道德”。',X+[['英语 extra- + mural〔接拉丁 mūrus〕','在围墙之外'],['英语 extramural','校外的；延伸到机构外的教学、活动或研究等']],'大学的 extramural courses 常面向校外社会人士，不只是在普通课程之外再多上一门课。具体机构也会用它区别内部和外部的项目，因此要看“墙”代表哪一条组织边界。','extramural courses；extramural studies；extramural research。','extracurricular 是正式课程以外，仍可能在校园里；extramural 强调学校或机构边界之外。',('The university offers extramural courses for local residents.','这所大学为当地居民开设校外教育课程。'),('She coordinates the college’s extramural education programme.','她负责协调学院面向校外人士的教育项目。'),sources=['https://www.collinsdictionary.com/dictionary/english/extramural','https://www.merriam-webster.com/dictionary/extramural']),
E('extravagant','/ɪkˈstrævəɡənt/','奢侈的；挥霍的；过分夸张的','像一条越走越远的路，花钱或说话超出了合理边界。','中世纪拉丁 extrāvagārī 是 extra-“在外” + vagārī“漫游”；分词 extrāvagāns 经拉丁、法语路线进入英语。不是现代 extra 后面接一个英语 vagant。',VAG,'an extravagant wedding 花费或排场过大；extravagant praise 则是赞美得过头，不涉及钱。是否“过度”取决于说话者的尺度，所以这个词常带评价。','extravagant spending；an extravagant gift；extravagant claims；be extravagant with money。','expensive 只说价格高；extravagant 还说花费、排场或程度超过必要。价格很高的救命设备不因此就叫 extravagant。',('They chose a simple dinner instead of an extravagant wedding reception.','他们选择了简单的聚餐，没有办奢华的婚宴。'),('The advertisement makes extravagant claims about the product.','这则广告对产品作出了夸张的宣称。'),sources=['https://www.etymonline.com/word/extravagant','https://www.etymonline.com/word/extravagance']),
E('extravagance','/ɪkˈstrævəɡəns/','奢侈；挥霍；奢侈的享受或物品','花费超出需要的做法；也可指自己允许的一次小奢侈。','借自法语 extravagance，接中世纪拉丁 extravagans 一系；现代可与 extravagant 对照，把 -ant 换成 -ance，但英语名词并非只能按本土派生解释。',VAG[:2]+[['法语 extravagant → extravagance','过度的状态或行为'],['英语 extravagance','奢侈、挥霍；一项奢侈享受']],'不可数时说一种挥霍作风；可数时 a small extravagance 可以很温和，比如偶尔买贵一点的花。它也能说言辞、想象过分铺张，不限于财政。','financial extravagance；a small extravagance；the extravagance of the claims。','luxury 可以中性指舒适的享受；extravagance 更容易带“本来不必花这笔”的意味。',('Fresh flowers every Friday are her one small extravagance.','每周五买鲜花，是她唯一的小奢侈。'),('The committee criticised the extravagance of the renovation plan.','委员会批评装修方案过于铺张。'),sources=['https://www.etymonline.com/word/extravagance'])
]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());family=next(r['family'] for r in m['roots'] if r['id']=='C0397');owned=set(m['owned_words'])
ROOT=[dict(id='C0397',meaning='在外面；超出范围',core='先画一条边界，再看什么落在边界外',image='在正常份额之外，多出 extra；在熟悉圈子之外，形成 strange；在数据范围之外推算，是 extrapolate；在合理花费之外走得太远，是 extravagant。',intro='拉丁 extrā 表示“在外面”，与 exterus“外面的”相联。最有用的不是死记“额外”，而是先问：外的是哪条边界？地球、细胞、课程、婚姻、领土，都能成为 extra- 后面的参照。',forms='extra- 是英语仍会使用的前缀。拉丁 extrāneus 经法语变化，成为 strange、estrange 一支；直接借入则形成 extraneous。exterior 来自拉丁比较级。独立词 extra 通常是 extraordinary 的缩略，不能把所有词都画成现代 extra 派生。',branches=[['份额与常态之外','extra、extraordinary、extraordinarily、extravagant、extravagance'],['陌生、疏远与无关','strange、strangely、strangeness、stranger、estrange、estranged、estrangement、extraneous'],['物理或组织边界','exterior、extraterrestrial、extracellular、extracurricular、extramural、extramarital、extrajudicial、extraterritorial'],['已知范围之外','extrapolate、extrapolation']],contrasts='extraterrestrial 是地外，extraterritorial 是域外。extracurricular 指课程外，extramural 指学校或机构边界外。strange 可只表示陌生，extraneous 则常表示与当前主题无关。extravagant 的漫游是词源画面，现代重点通常是花费或言辞过度。',practice='分别为 extra chair、extracellular fluid、extramarital affair、extrapolation 找出那条边界。再用一句话区分 stranger、foreigner 和 estranged family member。',words=list(family),sources=['https://www.etymonline.com/word/extra','https://www.etymonline.com/word/exterior','https://www.etymonline.com/word/extravagance'])]
assert {w['word'] for w in W}==set(family)&owned
for w in W:
 assert len(w['examples'])>=2 and len(w['history'])>=2 and w['ipa'],w['word']
 assert all(len(n)==2 and all(isinstance(v,str) and v for v in n) for n in w['history']),w['word']
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_30_extra.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('C0397',len(W),'new',len(family),'references',sum(len(w['examples']) for w in W),'examples')
